/* @lc app=leetcode id=1928 lang=kotlin */
class Solution { fun minCost(maxTime: Int, edges: Array<IntArray>, passingFees: IntArray): Int = IntArray(passingFees.size) { Int.MAX_VALUE }.let { minTime -> java.util.PriorityQueue<IntArray>(compareBy { it[1] }).apply { add(intArrayOf(0, passingFees[0], 0)) }.let { pq -> generateSequence { pq.poll() }.filter { it[2] < minTime[it[0]] }.onEach { cur -> cur.also { minTime[it[0]] = it[2] }.run { edges.filter { it[0] == cur[0] || it[1] == cur[0] }.map { e -> intArrayOf(if (e[0] == cur[0]) e[1] else e[0], cur[1] + passingFees[if (e[0] == cur[0]) e[1] else e[0]], cur[2] + e[2]) }.filter { nxt -> nxt[2] <= maxTime && nxt[2] < minTime[nxt[0]] }.forEach { pq.add(it) } } }.firstOrNull { it[0] == passingFees.size - 1 }?.get(1) ?: -1 } }